def compact_provenance(values: list[str], fallback: str) -> str:
    seen: set[str] = set()
    unique: list[str] = []
    for value in values:
        value = collapse_ws(value)
        if value and value not in seen:
            unique.append(value)
            seen.add(value)
    if not unique:
        return fallback
    joined = " | ".join(unique)
    return "Source: " + shorten_for_bullet(joined, 390)


